// Función para determinar la bahía según diferentes criterios
function determinarBahia(data) {
  // OPCIÓN 1: Por ID del calendario (reemplaza con los IDs reales)
  if (data.organizer && data.organizer.email) {
    if (data.organizer.email.includes('bahia1') || data.organizer.email === 'id_calendario_bahia1@gmail.com') {
      return 'Bahías 1';
    }
    if (data.organizer.email.includes('bahia2') || data.organizer.email === 'id_calendario_bahia2@gmail.com') {
      return 'Bahías 2';
    }
  }

  // OPCIÓN 2: Por título/resumen del evento
  if (data.summary) {
    if (data.summary.toLowerCase().includes('bahía 1') || data.summary.toLowerCase().includes('bahia 1')) {
      return 'Bahías 1';
    }
    if (data.summary.toLowerCase().includes('bahía 2') || data.summary.toLowerCase().includes('bahia 2')) {
      return 'Bahías 2';
    }
  }

  // OPCIÓN 3: Obtener desde el loop context (si viene del Excel)
  try {
    const loopItem = $("Loop Over Items").item.json;
    if (loopItem.Bahias || loopItem.bahias || loopItem.Bahía || loopItem.bahía) {
      const bahiaValue = loopItem.Bahias || loopItem.bahias || loopItem.Bahía || loopItem.bahía;
      return bahiaValue == 1 ? 'Bahías 1' : 'Bahías 2';
    }
    if (loopItem.Taller) {
      // Si el campo se llama "Taller" en tu Excel
      return loopItem.Bahias.includes('1') ? 'Bahías 1' : 'Bahías 2';
    }
  } catch (error) {
    // No se pudo obtener del loop context
  }

  // OPCIÓN 4: Por defecto, intentar deducir por otros campos
  return 'Bahía no identificada';
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;
  const bahia = determinarBahia(data);

  // Verificar si tiene dateTime (eventos con hora específica)
  if (data.start && data.start.dateTime && data.end && data.end.dateTime) {
    const dia = data.start.dateTime.split('T')[0];
    const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
    const final = data.end.dateTime.split('T')[1].substring(0, 5);

    returnItems.push({
      json: {
        dia: dia,
        inicio: inicio, 
        final: final,
        tipo: 'evento_con_hora',
        titulo: data.summary || 'Sin título',
        bahia: bahia,
        calendario_email: data.organizer?.email || 'No disponible'
      }
    });
  }
  // Verificar si tiene date (eventos de día completo, como feriados)
  else if (data.start && data.start.date) {
    const dia = data.start.date;

    returnItems.push({
      json: {
        dia: dia,
        inicio: '00:00', 
