function convertirAMinutos(hora) {
  const [horas, minutos] = hora.split(':').map(Number);
  return horas * 60 + minutos;
}

function convertirDesdeMinutos(minutosTotales) {
  const horas = Math.floor(minutosTotales / 60);
  const minutos = minutosTotales % 60;
  return `${horas.toString().padStart(2, '0')}:${minutos.toString().padStart(2, '0')}`;
}

function generarSlots(horaInicio, horaFin, duracionMinutos) {
  const slots = [];
  const inicio = convertirAMinutos(horaInicio);
  const fin = convertirAMinutos(horaFin);

  for (let minutos = inicio; minutos + duracionMinutos <= fin; minutos += duracionMinutos) {
    const slotInicio = convertirDesdeMinutos(minutos);
    const slotFin = convertirDesdeMinutos(minutos + duracionMinutos);

    slots.push({
      inicio: slotInicio,
      fin: slotFin
    });
  }

  return slots;
}

function hayConflictoConOcupados(horaInicio, horaFin, turnosOcupados) {
  const inicioSlot = convertirAMinutos(horaInicio);
  const finSlot = convertirAMinutos(horaFin);

  return turnosOcupados.some(turno => {
    const inicioOcupado = convertirAMinutos(turno.inicio);
    const finOcupado = convertirAMinutos(turno.final);
    // Verificar si hay solapamiento
    return (inicioSlot < finOcupado && finSlot > inicioOcupado);
  });
}

function esHorarioExcluido(horaInicio, horaFin) {
  const inicioMinutos = convertirAMinutos(horaInicio);
  const finMinutos = convertirAMinutos(horaFin);

  // Rangos excluidos en minutos
  const rangosExcluidos = [
    { inicio: convertirAMinutos("08:30"), fin: convertirAMinutos("10:00") },  // 8:30 - 10:00 AM
    { inicio: convertirAMinutos("10:30"), fin: convertirAMinutos("15:00") },  // 10:30 AM - 3:00 PM
    { inicio: convertirAMinutos("15:30"), fin: convertirAMinutos("16:00") },  // 3:30 - 4:00 PM
    { inicio: convertirAMinutos("16:00"), fin: convertirAMinutos("23:59") }   // 4:00 PM en adelante
  ];

  // Verificar si el slot se solapa con algún rango excluido
  return rangosExcluidos.some(rango => {
    return (inicioMinutos < rango.fin && finMinutos > rango.inicio);
  });
}

function generarFechasProximosDias(cantidadDias) {
  const fechas = [];
  const hoy = new Date();

  // Lista de feriados
  const feriados = [
    '2025-01-01', '2025-03-03', '2025-03-04', '2025-03-24', 
    '2025-04-18', '2025-04-02', '2025-05-01', '2025-05-25', 
    '2025-06-20', '2025-07-09', '2025-08-17', '2025-10-12', 
    '2025-11-24', '2025-12-08', '2025-12-25'
  ];

  let diasEncontrados = 0;
  let i = 1;

  // Empezar desde mañana y buscar días laborables
  while (diasEncontrados < cantidadDias) {
    const fecha = new Date(hoy);
    fecha.setDate(hoy.getDate() + i);

    const fechaFormateada = fecha.toISOString().split('T')[0];
    const dayOfWeek = fecha.getDay(); // 0=domingo, 1=lunes, ..., 6=sábado

    // Verificar si es día laborable (lunes a viernes) y no es feriado
    const esLaborable = dayOfWeek >= 1 && dayOfWeek <= 5;
    const noEsFeriado = !feriados.includes(fechaFormateada);

    if (esLaborable && noEsFeriado) {
      fechas.push(fechaFormateada);
      diasEncontrados++;
    }

    i++;
  }

  return fechas;
}

function calcularTurnosDisponibles(turnosOcupados, configuracion, cantidadDias) {
  const tiempo = configuracion.tiempo || 30; // duración por defecto 30 minutos

  // Extraer rangos horarios de forma dinámica
  const rangosHorarios = [];
  let index = 1;

  while (configuracion[`horarioInicio${index}`] && configuracion[`horarioFin${index}`]) {
    rangosHorarios.push({
      inicio: configuracion[`horarioInicio${index}`],
      fin: configuracion[`horarioFin${index}`]
    });
    index++;
  }

  // Si no se encontraron rangos, usar un rango predeterminado
  if (rangosHorarios.length === 0) {
    rangosHorarios.push({
      inicio: "08:00",
      fin: "18:00"
    });
  }

  // Generar fechas para los próximos días
  const fechasProximas = generarFechasProximosDias(cantidadDias);

  const turnosDisponibles = {};

  // Procesar cada día
  fechasProximas.forEach(dia => {
    turnosDisponibles[dia] = [];

    // Obtener turnos ocupados para este día específico
    const ocupadosDelDia = turnosOcupados.filter(turno => turno.dia === dia);

    // Procesar cada rango horario configurado
    rangosHorarios.forEach(rango => {
      // Generar todos los slots posibles en este rango
      const slotsEnRango = generarSlots(rango.inicio, rango.fin, tiempo);

      // Filtrar slots que NO están ocupados y NO están en horarios excluidos
      const slotsDisponibles = slotsEnRango.filter(slot => {
        const noEstaOcupado = !hayConflictoConOcupados(slot.inicio, slot.fin, ocupadosDelDia);
        const noEsHorarioExcluido = !esHorarioExcluido(slot.inicio, slot.fin);
        return noEstaOcupado && noEsHorarioExcluido;
      }).map(slot => ({
        dia: dia,
        inicio: slot.inicio,
        fin: slot.fin,
        fechaHora: `${dia} ${slot.inicio}-${slot.fin}`
      }));

      // Añadir slots disponibles al día
      turnosDisponibles[dia].push(...slotsDisponibles);
    });

    // Ordenar turnos por hora de inicio
    turnosDisponibles[dia].sort((a, b) => {
      const minutosA = convertirAMinutos(a.inicio);
      const minutosB = convertirAMinutos(b.inicio);
      return minutosA - minutosB;
    });
  });

  return turnosDisponibles;
}

// Calcular turnos disponibles
const resultado = calcularTurnosDisponibles(turnosOcupados, configuracion, diasAGenerar);

