function calcularSieteDiasLaborables() {
  const hoy = new Date();

  // Obtener los feriados del nodo anterior
  const feriadosData = $input.all(); // Obtiene todos los items del nodo anterior
  const feriados = [];

  // Extraer las fechas de los feriados del formato que recibes
  feriadosData.forEach(item => {
    if (item.json && item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    // Si el feriado dura más de un día, también agregar las fechas intermedias
    if (item.json && item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      // Agregar todas las fechas entre inicio y fin
      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  // Eliminar duplicados de la lista de feriados
  const feriadosUnicos = [...new Set(feriados)];

  let diasLaborablesEncontrados = 0;
  let i = 1; // Empezar desde mañana
  let fechaFinal = null;

  // Buscar hasta encontrar exactamente 7 días laborables
  while (diasLaborablesEncontrados < 7) {
    const fecha = new Date(hoy);
    fecha.setDate(hoy.getDate() + i);

    const fechaFormateada = fecha.toISOString().split('T')[0];
    const dayOfWeek = fecha.getDay(); // 0=domingo, 1=lunes, ..., 6=sábado

    // Verificar si es día laborable (lunes a viernes) y no es feriado
    const esLaborable = dayOfWeek >= 1 && dayOfWeek <= 5; // lunes a viernes
    const noEsFeriado = !feriadosUnicos.includes(fechaFormateada);

    if (esLaborable && noEsFeriado) {
      diasLaborablesEncontrados++;
      if (diasLaborablesEncontrados === 7) {
        // Establecer hora específica y formato completo
        fecha.setHours(12, 44, 14, 1); // 12:44:14.001
        fechaFinal = fecha.toISOString().replace('Z', '-04:00'); // Cambiar Z por -04:00
      }
    }

    i++;
  }

  return fechaFinal;
}

const sieteDias = calcularSieteDiasLaborables();

return [{
  json: {
    sieteDias: sieteDias,
    feriadosEncontrados: $input.all().length // Para debug: cantidad de feriados encontrados
  }
}];
